Translate("frFR", "hall-of-thanes", {
	title = "Hall of Thanes",
	aliases = { "The Hall of Thanes" },
	sections = {
		{
			title = "Résumé",
			text = [=[La Hall of Thanes s'étend dans les cavernes sous {link:old-ironforge}Old Ironforge{/link}, loin sous {link:high-seat}le High Seat{/link}. C'est un lieu de tombes et de caveaux, où les grands nains du passé d'{link:ironforge}Ironforge{/link} furent mis au repos et où les trésors de ses rois furent scellés. Pendant des générations, seuls ses gardiens y marchèrent. Désormais, les morts sont sans repos, et les {link:dark-iron-dwarves}Sombrefer{/link} ont fait irruption par en dessous.]=],
		},
		{
			title = "Origines",
			text = [=[Aucune chronique ne dit quand le premier thane fut mis au repos dans ces salles. Les caveaux, en leur point le plus profond, sont appelés le Reliquaire des rois. Parmi les reliques qui y étaient gardées se trouvait une tablette de pierre datant des jours qui suivirent la guerre des trois clans, quand Madoran devint le premier roi Bronzebeard d'{link:ironforge}Ironforge{/link} : le traité de paix entre les Bronzebeard et les Wildhammer, que les {link:dark-iron-dwarves}Sombrefer{/link} refusèrent de signer. Une autre chambre, le Repos d'Anvilmar, abrite la tombe d'un thane nommé {link:faldrim-anvilmar}Faldrim Anvilmar{/link}.]=],
		},
		{
			title = "L'incursion",
			text = [=[Le voyant de la terre {link:earthseer-farsen}Farsen{/link}, un Wildhammer en visite en {link:dun-morogh}Dun Morogh{/link}, fut le premier à voir le danger. Des espions sombrefer étaient venus dans le pays, et une carte prise sur leurs morts montrait des tunnels qui se rejoignaient sous {link:ironforge}Ironforge{/link}. Les {link:dark-iron-dwarves}Sombrefer{/link} montèrent dans les caveaux à bord de taupes mécaniques. Leurs pillards se mirent à dépouiller les tombes de leurs objets de famille, leurs ingénieurs lancèrent des bombes, et leurs invocateurs appelèrent le feu. Des golems de pierre marchent à leurs côtés. Au même moment, les esprits des morts s'éveillèrent, furieux et tourmentés, et se mirent à hanter leurs propres salles.]=],
		},
		{
			title = "Boss",
			text = [=[• {b}{link:faldrim-anvilmar}Faldrim Anvilmar{/link}{/b}, un thane d'autrefois dont l'esprit ne peut trouver le repos, consumé par une rancune ancienne.
• {b}{link:magmatus}Magmatus{/link}{/b}, une créature de feu vivant qui combat aux côtés d'un invocateur sombrefer.
• {b}Plunder{/b}, un élémentaire qui arpente une salle des caveaux et projette les intrus au loin.
• {b}{link:durgen-dirgehammer}Durgen Dirgehammer{/link}{/b}, le commandant de l'incursion sombrefer, gardé par des golems dans les caveaux inférieurs.]=],
		},
		{
			title = "De nos jours",
			text = [=[Les gardiens des tombes ne descendront pas dans la salle tant que les morts ne seront pas apaisés. Un {link:gnomes}gnome{/link} qui prétend qu'il patrouillait dans les caveaux veut qu'on remonte les objets de famille, et dit qu'il en dressera l'inventaire. Le voyant de la terre {link:earthseer-farsen}Farsen{/link} demande des volontaires pour descendre, trouver le commandant sombrefer et porter sa tête au roi. Le roi {link:magni-bronzebeard}Magni Bronzebeard{/link} a promis qu'une fois les envahisseurs partis, les brèches seraient scellées et les salles inférieures fortifiées, afin qu'aucun ennemi ne puisse plus jamais passer par là.]=],
		},
	},
})

Translate("frFR", "faldrim-anvilmar", {
	title = "Faldrim Anvilmar",
	subtitle = "Le thane sans repos",
	found = "Le Repos d'Anvilmar, dans la Hall of Thanes",
	allegiance = "Les morts d'Ironforge",
	aliases = { "Faldrim" },
	sections = {
		{
			title = "Résumé",
			text = [=[Faldrim Anvilmar était un thane d'{link:ironforge}Ironforge{/link}, mis au repos dans la chambre appelée le Repos d'Anvilmar. Quand les {link:dark-iron-dwarves}Sombrefer{/link} firent irruption dans les caveaux, son esprit s'éveilla avec les autres, et il ne s'éveilla pas en paix. Il arpente sa salle, consumé par une rancune ancienne, frappant l'esprit des vivants et jetant une malédiction sur ceux qui se dressent contre lui. Le fantôme de l'un de ceux qui le servirent supplie qu'on laisse enfin son thane reposer.]=],
		},
		{
			title = "Non consigné",
			text = [=[Faldrim porte le nom d'Anvilmar, le nom du haut roi sous lequel tous les nains furent jadis unis. Ce qui le liait à ce roi, et quelle rancune le tient aujourd'hui, aucune chronique ne le dit.]=],
		},
	},
	mentions = {
		{ text = "Une rancune ancienne" },
	},
	bonds = {
		{ id = "durgen-dirgehammer", name = "Durgen Dirgehammer", note = "l'envahisseur de sa tombe" },
	},
})

Translate("frFR", "magmatus", {
	title = "Magmatus",
	subtitle = "Le feu des Sombrefer",
	found = "La Hall of Thanes",
	allegiance = "Nains Sombrefer",
	sections = {
		{
			title = "Résumé",
			text = [=[Magmatus est une créature de feu vivant venue dans la {link:hall-of-thanes}Hall of Thanes{/link} avec les {link:dark-iron-dwarves}Sombrefer{/link}. Un invocateur sombrefer se tient à ses côtés, et les flammes qui jaillissent de lui submergent tous ceux qui sont proches. Les Sombrefer servent les seigneurs du feu depuis la chute de leur cité de {link:ruins-of-thaurissan}Thaurissan{/link}, et leurs invocateurs apportent le feu partout où ils vont. Dans les tombes des thanes, parmi les vieilles pierres d'{link:ironforge}Ironforge{/link}, Magmatus brûle comme le signe de ceux qui sont venus.]=],
		},
		{
			title = "Importance",
			text = [=[Magmatus montre que l'incursion sombrefer n'est pas une simple bande de voleurs. Ceux qui vinrent sous {link:ironforge}Ironforge{/link} apportèrent avec eux le pouvoir de leurs maîtres.]=],
		},
	},
})

Translate("frFR", "plunder", {
	title = "Plunder",
	subtitle = "Gardien des caveaux",
	found = "Une salle des caveaux, dans la Hall of Thanes",
	allegiance = "Inconnue",
	sections = {
		{
			title = "Résumé",
			text = [=[Plunder est un être élémentaire qui arpente l'une des longues salles de la {link:hall-of-thanes}Hall of Thanes{/link}. Il frappe avec une telle force que ceux qu'il touche sont projetés à travers la chambre. Qu'il serve les {link:dark-iron-dwarves}Sombrefer{/link}, garde les caveaux des rois ou soit simplement entré par les brèches depuis les lieux profonds, les gardiens de la salle ne l'ont pas dit.]=],
		},
		{
			title = "Non consigné",
			text = [=[Rien n'est écrit sur l'origine de Plunder ni sur celui à qui il obéit. Son nom est tout ce que l'on sait, et il convient assez bien aux affaires des {link:dark-iron-dwarves}Sombrefer{/link} dans les caveaux.]=],
		},
	},
})

